const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json.body || item.json || {};
  const hasExplicitMembers = Array.isArray(payload.members) && payload.members.length > 0;
  const hasExplicitData = Boolean(payload.data && (Array.isArray(payload.data) || payload.data.membership_id));
  const isScheduled = !hasExplicitMembers && !hasExplicitData;

  results.push({
    json: {
      ...payload,
      isScheduled,
      tenantId: payload.tenantId || $env.DEFAULT_TENANT_ID || 'demo'
    }
  });
}

return results;

const items = $input.all();
const results = [];
const today = new Date();
today.setHours(0, 0, 0, 0);

for (const item of items) {
  const payload = item.json.body || item.json || {};
  let rawMembers = [];

  if (Array.isArray(payload.members)) {
    rawMembers = payload.members;
  } else if (Array.isArray(payload.data)) {
    rawMembers = payload.data;
  } else if (payload.data?.memberships && Array.isArray(payload.data.memberships)) {
    rawMembers = payload.data.memberships;
  } else if (payload.memberships && Array.isArray(payload.memberships)) {
    rawMembers = payload.memberships;
  } else if (payload.membership_id || payload.id) {
    rawMembers = [payload];
  }

  for (const m of rawMembers) {
    if (!m) continue;

    let days = typeof m.days_until_expiry !== 'undefined' ? Number(m.days_until_expiry) : null;
    const expiryDateStr = m.expiry_date || m.end_date || '';

    if (days === null && expiryDateStr) {
      const expDate = new Date(expiryDateStr);
      expDate.setHours(0, 0, 0, 0);
      days = Math.round((expDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    }

    if (days === null) days = 7;

    // Only remind for 7d, 3d, 1d, or 0d (expired today)
    if (![7, 3, 1, 0].includes(days) && !payload.isManualTest) {
      continue;
    }

    let templateName = 'renewal-reminder-7d';
    if (days === 3) {
      templateName = 'renewal-reminder-3d';
    } else if (days === 1) {
      templateName = 'renewal-reminder-1d';
    } else if (days <= 0) {
      templateName = 'membership-expired';
    }

    const memberName = m.member_name || m.name || 'Valued Member';
    const planName = m.plan_name || m.plan || 'Studio Membership';
    const expiryDate = expiryDateStr || new Date().toISOString().split('T')[0];
    const phone = m.phone || m.to || '+910000000000';
    const memberId = m.member_id || m.id || `mem_${Date.now()}`;
    const renewalLink = m.renewal_link || `https://${payload.tenantId || 'demo'}.fitness.local/member/my-membership`;

    results.push({
      json: {
        to: phone,
        phone,
        template: templateName,
        template_name: templateName,
        tenantId: payload.tenantId || m.tenantId || 'default-tenant',
        eventId: `renew_${memberId}_${days}d`,
        correlationId: `corr_${Date.now()}`,
        idempotencyKey: `renewal_${memberId}_${templateName}_${expiryDate}`,
        isDirectDelivery: true,
        source: 'domain_workflow',
        workflow_name: 'renewal-reminders',
        data: {
          member_name: memberName,
          plan_name: planName,
          expiry_date: expiryDate,
          renewal_link: renewalLink,
          days_remaining: days
        }
      }
    });
  }
}

return results.length > 0 ? results : [{
  json: {
    processed: 0,
    message: 'No expiring memberships eligible for renewal reminders.'
  }
}];

